css:
.print-format {
    color: #111;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 8.4pt;
    line-height: 1.24;
    page-size: A4;
    padding: 0 !important;
}

.print-format table {
    border-collapse: collapse;
    margin: 0;
    table-layout: fixed;
    width: 100%;
}

.omr-page {
    position: relative;
    width: 100%;
}

.second-page {
    page-break-inside: avoid;
    padding-top: 3mm;
}

.omr-running-header {
    border-bottom: 1px solid #9d9d9d;
    color: #555;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 7.5pt;
    margin-bottom: 2mm;
    width: 100%;
}

.omr-running-header td {
    border: 0 !important;
    padding: 0 0 1.7mm !important;
    vertical-align: bottom !important;
}

.brand-cell {
    width: 15%;
}

.brand-mark {
    color: #2f50e7;
    font-size: 15pt;
    font-weight: 800;
    letter-spacing: -0.08em;
}

.header-reference {
    text-align: left;
}

.document-title {
    font-size: 16.5pt;
    font-weight: 750;
    line-height: 1.06;
    margin-top: 1mm;
    text-align: center;
}

.document-acronym {
    font-size: 15pt;
    font-weight: 750;
    line-height: 1.05;
    text-align: center;
}

.template-reference {
    color: #2f50e7;
    font-size: 8.5pt;
    font-weight: 700;
    margin-top: 1mm;
    text-align: center;
}

.scope-note {
    color: #666;
    font-size: 7.6pt;
    font-style: italic;
    margin: 1mm auto 6mm;
    max-width: 94%;
    text-align: center;
}

.document-watermark {
    border: 1px solid #d1a500;
    color: #a88300;
    font-size: 7pt;
    font-weight: 700;
    letter-spacing: 0.12em;
    padding: 1mm 2mm;
    position: absolute;
    right: 0;
    top: 0;
}

.document-watermark.cancelled {
    border-color: #bb3030;
    color: #bb3030;
}

.identity-table {
    border: 1px solid #111;
    margin-bottom: 5mm !important;
    page-break-inside: avoid;
}

.identity-table th,
.identity-table td {
    border: 1px solid #111 !important;
    padding: 1.35mm 2.5mm !important;
    vertical-align: middle !important;
}

.identity-table th {
    background: #efefef;
    font-weight: 700;
    text-align: left;
    width: 29%;
}

.reference-value {
    font-weight: 700;
}

.section-title {
    background: #a9a9a9;
    color: #fff;
    font-size: 9.2pt;
    font-weight: 700;
    line-height: 1;
    margin: 4.2mm 0 0;
    padding: 1.4mm 1.2mm;
    page-break-after: avoid;
}

.section-title.first-section {
    margin-top: 0;
}

.question {
    font-weight: 700;
    page-break-after: avoid;
}

.answer-question {
    margin-top: 3.5mm;
}

.guidance {
    color: #6b6b6b;
    font-size: 7.5pt;
    font-style: italic;
    margin: 0.4mm 0 0.6mm;
}

.choice-grid td {
    border: 0 !important;
    padding: 0.45mm 0.5mm 0.25mm 0 !important;
    vertical-align: top !important;
    width: 50%;
}

.check-box {
    border: 1px solid #333;
    display: inline-block;
    font-size: 7.5pt;
    font-weight: 700;
    height: 3.2mm;
    line-height: 2.8mm;
    margin-right: 1mm;
    text-align: center;
    vertical-align: -0.4mm;
    width: 3.2mm;
}

.check-box.checked {
    border-color: #111;
    color: #111;
}

.check-box.spaced {
    margin-left: 3.5mm;
}

.other-choice {
    margin-top: 0.35mm;
}

.inline-answer {
    border-bottom: 0.8px solid #333;
    display: inline-block;
    min-height: 3.4mm;
    padding: 0 1mm;
    vertical-align: bottom;
    width: 78%;
}

.inline-answer.wide {
    width: 76%;
}

.text-answer {
    border-bottom: 0.8px solid #444;
    min-height: 5mm;
    padding: 0.8mm 0;
    page-break-inside: avoid;
    white-space: pre-wrap;
    word-break: break-word;
}

.text-answer.large-answer {
    min-height: 13mm;
}

.text-answer.medium-answer {
    min-height: 8mm;
}

.text-answer.single-answer {
    min-height: 4.5mm;
}

.training-line {
    margin-top: 3.4mm;
}

.actions-table {
    border: 1px solid #111;
    margin-top: 5mm !important;
    page-break-inside: auto;
}

.actions-table th,
.actions-table td {
    border: 1px solid #111 !important;
    padding: 1.8mm 2mm !important;
    vertical-align: middle !important;
}

.actions-table thead {
    display: table-header-group;
}

.actions-table th {
    background: #aaa;
    color: #fff;
    font-weight: 700;
    text-align: left;
}

.actions-table tr {
    page-break-inside: avoid;
}

.actions-table .action-column {
    width: 52%;
}

.actions-table .responsible-column {
    width: 20%;
}

.actions-table .date-column {
    width: 16%;
}

.actions-table .done-column {
    width: 12%;
}

.blank-action-row td {
    height: 7.5mm;
}

.pre-line {
    white-space: pre-wrap;
    word-break: break-word;
}

.center {
    text-align: center;
}

.review-line {
    margin-top: 4mm;
}

.review-other {
    width: 17%;
}

.decision-line {
    margin-top: 4mm;
}

.approval-table {
    border: 1px solid #111;
    margin-top: 5mm !important;
    page-break-inside: avoid;
}

.approval-table th,
.approval-table td {
    border: 1px solid #111 !important;
    height: 9mm;
    padding: 1.2mm 2mm !important;
    vertical-align: middle !important;
}

.approval-table th {
    background: #aaa;
    color: #fff;
    font-weight: 700;
    text-align: left;
}

.approval-table th:nth-child(1),
.approval-table td:nth-child(1) {
    width: 34%;
}

.approval-table th:nth-child(2),
.approval-table td:nth-child(2) {
    width: 34%;
}

.approval-table th:nth-child(3),
.approval-table td:nth-child(3) {
    width: 17%;
}

.approval-table th:nth-child(4),
.approval-table td:nth-child(4) {
    width: 15%;
}

.not-applicable td {
    color: #777;
}

.signature-cell {
    padding: 0.5mm !important;
    text-align: center;
}

.signature-image {
    display: inline-block;
    max-height: 8mm;
    max-width: 27mm;
}

.effective-date-line {
    margin-top: 4mm;
}

.date-answer {
    text-align: center;
    width: 25%;
}

.effectiveness-line {
    margin-top: 3mm;
}

.closure-follow-up {
    border-left: 2px solid #999;
    margin-top: 2mm;
    padding: 1.5mm 2mm;
    page-break-inside: avoid;
}

.closure-visa-table {
    margin-top: 4mm !important;
    page-break-inside: avoid;
}

.closure-visa-table th,
.closure-visa-table td {
    border: 0 !important;
    border-bottom: 0.8px solid #333 !important;
    height: 8mm;
    padding: 1mm !important;
    vertical-align: middle !important;
}

.closure-visa-table th {
    text-align: left;
    width: 22%;
}

.closure-visa-table .closure-reviewer {
    width: 23%;
}

.closure-visa-table .signature-cell {
    width: 24%;
}

.closure-visa-table .closure-date-label {
    text-align: right;
    width: 9%;
}

.closure-visa-table .closure-date {
    text-align: center;
    width: 22%;
}

.omr-inline-footer {
    border-top: 1px solid #bbb;
    color: #777;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 7pt;
    margin-top: 7mm;
    padding-top: 1.6mm;
    text-align: center;
}

@media screen {
    .omr-page {
        border-bottom: 1px dashed #ccc;
        margin-bottom: 10mm;
        padding-bottom: 8mm;
    }
}
